mapper.select:
SELECT
u.*,
ud.user_id,
ud.trade_id,
ud.company_id,
ud.anchor_type,
ud.position,
ud.email,
ud.id_card,
ud.real_name,
ud.sex,
ud.birthday,
ud.address,
ud.channel_id,
ud.sale_id as sales_id,
ud.wx_name,
ud.agent_sale_id,
ud.is_show,
ud.video_meet_path,
ud.user_ambition,
ud.user_belong_type,
ud.is_logged_in,
ud.agent_id,
ud.is_submit_appointment,
tar.user_id AS analysis_user_id,
tar.analysis_sum AS sum_analysis,
tar.day_average_analysis AS day_analysis,
tar.last_analysis as last_analysis,
DATEDIFF(NOW(), tar.last_analysis) as long_not_analysis,
tar.contrast_analysis AS contrast_analysis,
tar.own_count AS own_count,
o.package_id,
o.end_date AS expiration_date,
ub.client_version AS clientVersion,
o.trial_order as trial_order,
upr.user_power_consume AS user_power_consume,
tpr.tenant_power_consume AS tenant_power_consume
FROM
tb_user u
LEFT JOIN tb_user_details ud ON u.id = ud.user_id AND ud.is_deleted = 0
LEFT JOIN tb_user_analysis_rollup tar ON u.id = tar.user_id AND tar.is_deleted = 0
LEFT JOIN tb_user_business ub ON u.id = ub.user_id

LEFT JOIN tb_user_power_rollup upr ON upr.user_id = u.id AND upr.tenant_id = u.active_tenant_id AND upr.is_deleted = 0

LEFT JOIN tb_tenant_power_rollup tpr ON tpr.tenant_id = u.active_tenant_id AND tpr.is_deleted = 0
LEFT JOIN (
SELECT
user_id, commodity_id AS package_id, MIN(trial_order) as trial_order, if(max(level) >= 0, MAX(end_date), null)
AS end_date
FROM tb_order
WHERE is_deleted = 0
AND commodity_type = 1
AND `status` IN (1, 2)
GROUP BY user_id
) o ON if(u.parent_id > 0, u.parent_id, u.id) = o.user_id


    INNER JOIN tb_sales s on ud.sale_id = s.id



    INNER JOIN tb_invite_url_code iuc ON u.invite_url_code = iuc.url_code AND iuc.is_deleted = 0
    INNER JOIN tb_agent_promotion ap ON iuc.promotion_id = ap.id

WHERE
u.is_deleted = 0
AND u.user_type in (0, 2)



    AND u.id IN

        #{id}





    AND ud.company_id IN

        #{id}





    AND (
    u.phone LIKE CONCAT('%', #{bo.keyword}, '%')
    OR u.nick_name LIKE CONCAT('%', #{bo.keyword}, '%')
    OR u.username LIKE CONCAT('%', #{bo.keyword}, '%')
    )




    AND u.nick_name LIKE CONCAT('%', #{bo.nickName}, '%')




    AND u.phone LIKE CONCAT('%', #{bo.phone}, '%')




    AND u.id = #{bo.id}




    AND u.parent_id = #{bo.parentId}




    AND ud.wx_name LIKE CONCAT('%', #{bo.userWxName}, '%')




    AND ud.trade_id = #{bo.tradeId}




    AND ud.is_logged_in = #{bo.isLoggedIn}




    AND ud.is_submit_appointment = #{bo.isSubmitAppointment}




    AND ud.sale_id = #{bo.salesId}



    AND ud.agent_id = #{bo.agentId}




    AND tar.day_average_analysis >= #{bo.startDayAnalysis}


    AND tar.day_average_analysis <= #{bo.endDayAnalysis}




    AND DATEDIFF(NOW(), tar.last_analysis) >= #{bo.startLongNotAnalysis}


    AND DATEDIFF(NOW(), tar.last_analysis) <= #{bo.endLongNotAnalysis}




    AND u.create_date >= #{bo.startTime}


    AND u.create_date <= #{bo.endTime}




    AND ud.channel_id = #{bo.channelId}




    AND ud.user_belong_type = #{bo.userBelongType}




    AND ud.user_ambition = #{bo.userAmbition}




    AND tar.own_count >= #{bo.ownCount}




    AND u.user_type = #{bo.userType}




    AND o.package_id = #{bo.packageId}




    AND o.trial_order = #{bo.trialOrder}




    AND DATEDIFF(o.end_date, NOW()) <= #{bo.expireTime}




    AND s.sales_type = #{bo.salesType}




    AND ap.promotion_name LIKE CONCAT('%', #{bo.promotionName}, '%')




    AND s.employee_status = #{bo.employeeStatus}




    AND ub.client_version = #{bo.clientVersion}



ORDER BY


        tar.own_count ${bo.sortOrder}


        o.end_date ${bo.sortOrder}


        tar.analysis_sum ${bo.sortOrder}


        tar.day_average_analysis ${bo.sortOrder}


        tar.contrast_analysis ${bo.sortOrder}


        DATEDIFF(NOW(), tar.last_analysis) ${bo.sortOrder}


        u.create_date DESC

SELECT u.id, ud.wx_name, u.phone, ud.channel_id, ud.sale_id as sales_id, ud.user_ambition as user_ambition, ud.user_belong_type as user_belong_type, o1.end_date AS expiration_one_date, o2.end_date AS expiration_two_date, o1.trial_order as trial_order, o1.level as `level`, o2.level as `level_two` FROM tb_user u LEFT JOIN tb_user_details ud ON u.id = ud.user_id LEFT JOIN ( SELECT user_id, max(level) as `level`, MIN(trial_order) AS trial_order, MAX(end_date) AS end_date FROM tb_order WHERE is_deleted = 0 AND commodity_type = 1 AND `status` IN (1, 2) GROUP BY user_id) o1 ON IF(u.parent_id > 0, u.parent_id, u.id) = o1.user_id
LEFT JOIN ( SELECT user_id, SUBSTRING_INDEX(MAX(CONCAT(real_end_date, '-', trial_order)), '-', -1) AS trial_order, SUBSTRING_INDEX(MAX(CONCAT(real_end_date, '-', `level`)), '-', -1) AS `level`, MAX(real_end_date) AS end_date FROM tb_order WHERE is_deleted = 0 AND commodity_type = 1 AND `status` IN (3, 4, 5, 8) AND `level` > 0 GROUP BY user_id) o2 ON IF(u.parent_id > 0, u.parent_id, u.id) = o2.user_id
u.is_deleted = 0 AND u.user_type = 0 AND o1.user_id IS NOT NULL
AND ud.user_ambition = #{bo.userAmbition}
AND ud.user_belong_type = #{bo.userBelongType}
AND ud.channel_id = #{bo.channelId}
AND ud.sale_id = #{bo.salesId}
AND ( u.phone LIKE CONCAT('%', #{bo.keyword}, '%') OR ud.wx_name LIKE CONCAT('%', #{bo.keyword}, '%') )
AND o1.trial_order = #{bo.trialOrder}
AND o2.trial_order = #{bo.trialOrder}
AND o1.level = #{bo.level}
AND o1.level = #{bo.level}
AND o2.level = #{bo.level}
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 3 * 24
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 7 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -3 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -7 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) < -7 * 24
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 15 * 24
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 30 * 24
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 60 * 24
and o1.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 90 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -7 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -15 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -30 * 24
and o1.level <= 0 AND TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -60 * 24
order by u.id desc

select count(if(TIMESTAMPDIFF(HOUR, NOW(), o.end_date) <= 72, 1, null)) as within3Days, count(if(TIMESTAMPDIFF(HOUR, NOW(), o.end_date) <= 168, 1, null)) as within7Days from tb_user u inner JOIN ( SELECT user_id, MIN(trial_order) AS trial_order, max(level) as `level`, if(max(level) >= 0, MAX(end_date), null) AS end_date FROM tb_order WHERE is_deleted = 0 AND commodity_type = 1 AND `status` IN (1, 2) GROUP BY user_id ) o ON if(u.parent_id > 0, u.parent_id, u.id) = o.user_id
u.is_deleted = 0 AND u.user_type = 0 and o.level > 0 AND TIMESTAMPDIFF(HOUR, NOW(), o.end_date) <= 7 * 24
AND o.trial_order = #{trialOrder}

select count(if(TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -72, 1, null)) as expired3Days, count(if(TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) >= -168, 1, null)) as expired7Days, count(if(TIMESTAMPDIFF(HOUR, NOW(), o2.end_date) < -168, 1, null)) as outside7Days from tb_user u inner JOIN ( SELECT user_id, max(level) AS level FROM tb_order WHERE is_deleted = 0 AND commodity_type = 1 AND `status` = 2 GROUP BY user_id ) o1 ON if(u.parent_id > 0, u.parent_id, u.id) = o1.user_id inner JOIN ( SELECT user_id, SUBSTRING_INDEX(MAX(CONCAT(real_end_date, '-', trial_order)), '-', -1) AS trial_order, MAX(real_end_date) AS end_date FROM tb_order WHERE is_deleted = 0 AND commodity_type = 1 AND `status` IN (3, 4, 5, 8) and `level` > 0 GROUP BY user_id ) o2 ON if(u.parent_id > 0, u.parent_id, u.id) = o2.user_id
u.is_deleted = 0 AND u.user_type = 0 and o1.level <= 0
AND o2.trial_order = #{trialOrder}

SELECT
u.*
FROM tb_user u left join tb_user_details ud on u.id = ud.user_id

    and u.is_deleted = 0
    and u.id > 1

        AND (u.username LIKE CONCAT('%', #{bo.keyword}, '%')
        OR u.nick_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR phone LIKE CONCAT('%', #{bo.keyword}, '%'))


        AND u.parent_id = #{bo.parentId}


        AND u.user_type = #{bo.userType}


        AND u.status = #{bo.status}


        AND u.username LIKE CONCAT('%', #{bo.userName}, '%')


        AND u.nick_name LIKE CONCAT('%', #{bo.nickName}, '%')


        AND u.phone LIKE CONCAT('%', #{bo.phone}, '%')


        AND u.id IN

            #{id}



        AND u.create_date >= #{bo.startTime}


        AND u.create_date <= #{bo.endTime}


        AND ud.employee_status = #{bo.employeeStatus}


order by u.id desc

SELECT u.id as user_id, ud.wx_name, u.phone, u.create_date as register_date, o1.commodity_name as packageName, o1.level as packageLevel, ud.user_ambition, TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) as packageExpires, o1.end_date as packageExpiresTime, ub.according_status, ub.according_content, ub.according_date, ub.next_fol_time FROM tb_user u inner join tb_user_details ud on ud.user_id = u.id inner join ( select user_id, max(real_end_date) AS end_date, max(tb_order.level) as level, max(commodity_name) as commodity_name from tb_order where is_deleted = 0 AND commodity_type = 1 AND trial_order = 1 AND status in (1, 2) and level > 0 group by user_id ) o1 ON u.id = o1.user_id left join tb_user_business ub on u.id = ub.user_id WHERE u.is_deleted = 0 AND u.user_type = 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 3 * 24
AND ud.sale_id = #{bo.salesId}
ORDER BY
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ${bo.sortOrder}
o1.end_date ${bo.sortOrder}
ub.according_status ${bo.sortOrder}
o1.level ${bo.sortOrder}
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ASC

SELECT u.id as user_id, ud.wx_name, u.phone, u.create_date as register_date, o1.commodity_name as packageName, o1.level as packageLevel, ud.user_ambition, TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) as packageExpires, o1.end_date as packageExpiresTime, ub.according_status, ub.according_content, ub.according_date, ub.next_fol_time FROM tb_user u inner join tb_user_details ud on ud.user_id = u.id inner join tb_user_business ub on u.id = ub.user_id left join (select user_id, max(real_end_date) AS end_date, max(tb_order.level) as level, max(commodity_name) as commodity_name from tb_order where is_deleted = 0 AND commodity_type = 1 AND status in (1, 2) GROUP BY user_id) o1 ON u.id = o1.user_id # left JOIN (SELECT user_id # FROM tb_order # WHERE is_deleted = 0 # AND commodity_type = 1 # AND trial_order = 0 # AND `status` IN (1, 2, 3, 4, 5, 8) # AND `level` > 0 # GROUP BY user_id) o2 ON u.id = o2.user_id WHERE u.is_deleted = 0 AND u.user_type = 0 # AND o2.user_id is null
AND DATEDIFF(ub.next_fol_time, NOW()) BETWEEN 0 AND 3
AND DATEDIFF(ub.next_fol_time, NOW()) BETWEEN -3 AND -1
AND ud.sale_id = #{bo.salesId}
ORDER BY
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ${bo.sortOrder}
o1.end_date ${bo.sortOrder}
ub.according_status ${bo.sortOrder}
o1.level ${bo.sortOrder}
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ASC

SELECT u.id as user_id, ud.wx_name, u.phone, u.create_date as register_date, o1.commodity_name as packageName, o1.level as packageLevel, ud.user_ambition, TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) as packageExpires, o1.end_date as packageExpiresTime, ub.according_status, ub.according_content, ub.according_date, ub.next_fol_time FROM tb_user u inner join tb_user_details ud on ud.user_id = u.id inner join (select user_id, max(real_end_date) AS end_date, max(tb_order.level) as level, max(commodity_name) as commodity_name from tb_order where is_deleted = 0 AND commodity_type = 1 AND trial_order = 0 AND status in (1, 2) AND level > 0 group by user_id) o1 ON u.id = o1.user_id left join tb_user_business ub on u.id = ub.user_id WHERE u.is_deleted = 0 AND u.user_type = 0 AND TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) <= 15 * 24
AND ud.sale_id = #{bo.salesId}
ORDER BY
o1.level ${bo.sortOrder}
o1.end_date ${bo.sortOrder}
ub.according_status ${bo.sortOrder}
o1.level ${bo.sortOrder}
o1.level ASC

SELECT ud.user_ambition as user_ambition, count(1) as user_count FROM dept_user du INNER JOIN tb_sales s ON s.user_id = du.user_id INNER JOIN tb_user_details ud ON ud.sale_id = s.id INNER JOIN tb_user u ON ud.user_id = u.id INNER join ( select user_id, max(real_end_date) AS end_date from tb_order where is_deleted = 0 AND commodity_type = 1 AND trial_order = 1 AND status in (1, 2) and level > 0 GROUP BY user_id ) o1 ON u.id = o1.user_id WHERE u.is_deleted = 0 AND u.user_type = 0
AND o1.end_date <= #{bo.endDate}
group by ud.user_ambition

SELECT u.id as user_id, ud.wx_name, u.phone, u.create_date as register_date, o1.commodity_name as packageName, o1.level as packageLevel, ud.user_ambition, TIMESTAMPDIFF(HOUR, NOW(), o1.end_date) as packageExpires, o1.end_date as packageExpiresTime, ub.according_status, ub.according_content, ub.according_date, ub.next_fol_time, s.sales_name as sales_name, s.id as sales_id FROM dept_user du INNER JOIN tb_sales s ON s.user_id = du.user_id INNER JOIN tb_user_details ud ON ud.sale_id = s.id INNER JOIN tb_user u ON ud.user_id = u.id INNER join ( select user_id, max(real_end_date) AS end_date, max(tb_order.level) as level, max(commodity_name) as commodity_name from tb_order where is_deleted = 0 AND commodity_type = 1 AND trial_order = 1 AND status in (1, 2) and level > 0 GROUP BY user_id ) o1 ON u.id = o1.user_id left join tb_user_business ub on u.id = ub.user_id WHERE u.is_deleted = 0 AND u.user_type = 0
AND ud.user_ambition = #{bo.userAmbition}
AND o1.end_date <= #{bo.endDate}
ORDER BY
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ${bo.sortOrder}
o1.end_date ${bo.sortOrder}
ub.according_status ${bo.sortOrder}
o1.level ${bo.sortOrder}
CASE ud.user_ambition WHEN 'S' THEN 5 WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 6 END ASC

SELECT s.id as salesId, count(1) AS registerUserNum, count(IF(ud.is_logged_in = 1, 1, NULL)) AS loginUserNum, count(IF(ud.is_show = 1, 1, NULL)) AS demoNum FROM tb_sales s INNER JOIN tb_user_details ud ON ud.sale_id = s.id INNER JOIN tb_user u ON ud.user_id = u.id WHERE s.id IN
#{id}
AND u.is_deleted = 0 AND u.user_type = 0 AND u.create_date BETWEEN #{bo.startDate} AND #{bo.endDate} GROUP BY s.id

SELECT s.id as salesId, COUNT(DISTINCT CASE WHEN o.trial_order = 1 AND o.commodity_type = 1 AND o.level > 0 THEN o.user_id END) AS trialUserNum, COUNT(DISTINCT CASE WHEN o.trial_order = 1 AND o.commodity_type = 1 AND o.level > 0 and ud.is_logged_in = 1 THEN o.user_id END) AS trialLoginUserNum, COUNT(DISTINCT CASE WHEN o.trial_order = 0 THEN o.user_id END) AS customerNum, IFNULL(SUM(CASE WHEN o.trial_order = 0 THEN o.total_price ELSE 0 END), 0) AS customerAmount FROM tb_order AS o INNER JOIN tb_user u ON o.user_id = u.id INNER JOIN tb_user_details ud ON ud.user_id = u.id INNER JOIN tb_sales s ON ud.sale_id = s.id WHERE s.id IN
#{id}
AND u.is_deleted = 0 AND u.user_type = 0 AND o.is_deleted = 0 AND u.create_date BETWEEN #{bo.startDate} AND #{bo.endDate} GROUP BY s.id
